{
  "name": "harness-mdocs",
  "version": "2.2.0",
  "description": "Surface-neutral initiative and wiki memory for AI coding harnesses.",
  "license": "MIT",
  "author": "bbaaxx",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bbaaxx/harness-mdocs.git"
  },
  "keywords": [
    "mdocs",
    "memory",
    "workflow",
    "initiative",
    "wiki",
    "codex",
    "opencode",
    "pi"
  ],
  "engines": {
    "node": ">=18.0.0"
  },
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "mdocs": "dist/cli/index.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./api": {
      "types": "./dist/api.d.ts",
      "default": "./dist/api.js"
    },
    "./core": {
      "types": "./dist/core/index.d.ts",
      "default": "./dist/core/index.js"
    },
    "./agents": {
      "types": "./dist/agents/index.d.ts",
      "default": "./dist/agents/index.js"
    },
    "./opencode": {
      "types": "./dist/surfaces/opencode/index.d.ts",
      "default": "./dist/surfaces/opencode/index.js"
    },
    "./plugin": {
      "types": "./dist/surfaces/opencode/opencode.d.ts",
      "default": "./dist/surfaces/opencode/opencode.js"
    },
    "./codex": {
      "types": "./dist/surfaces/codex/index.d.ts",
      "default": "./dist/surfaces/codex/index.js"
    },
    "./claude-code": {
      "types": "./dist/surfaces/claude-code/index.d.ts",
      "default": "./dist/surfaces/claude-code/index.js"
    },
    "./pi": {
      "types": "./dist/surfaces/pi/index.d.ts",
      "default": "./dist/surfaces/pi/index.js"
    },
    "./kimi-code": {
      "types": "./dist/surfaces/kimi-code/index.d.ts",
      "default": "./dist/surfaces/kimi-code/index.js"
    }
  },
  "pi": {
    "extensions": [
      "./dist/surfaces/pi/extension.js"
    ],
    "skills": [
      "./src/surfaces/pi/assets/skills"
    ]
  },
  "scripts": {
    "build": "node scripts/write-build-info.js && node scripts/stamp-versions.js && tsc",
    "clean": "rimraf dist",
    "typecheck": "tsc --noEmit",
    "lint": "npm run typecheck",
    "test": "jest",
    "test:core": "jest tests/core",
    "test:opencode": "jest tests/surfaces/opencode",
    "test:codex": "jest tests/surfaces/codex",
    "test:claude-code": "jest tests/surfaces/claude-code",
    "test:pi": "jest tests/surfaces/pi",
    "test:kimi-code": "jest tests/surfaces/kimi-code",
    "coverage": "jest --coverage",
    "mdocs:lint": "npm run build && node dist/cli/index.js validate",
    "mdocs:validate": "npm run mdocs:lint",
    "generate:agents": "node scripts/generate-agent-assets.js --generate",
    "check:agents": "node scripts/generate-agent-assets.js --check",
    "check:versions": "node scripts/stamp-versions.js --check",
    "pack:check": "npm pack --dry-run",
    "quality": "npm run build:claude-plugin && npm run build:kimi-plugin && npm run check:agents && npm run check:versions && npm run lint && npm test && npm run coverage && npm run mdocs:validate",
    "release:check": "npm run quality && npm run pack:check",
    "build:claude-plugin": "bash scripts/build-claude-plugin.sh",
    "build:claude-plugin:mcp": "esbuild src/surfaces/claude-code/mcp-server.ts --bundle --platform=node --target=node18 --format=cjs --sourcemap --outfile=src/surfaces/claude-code/plugin/dist/cli/mcp-server.js",
    "build:kimi-plugin": "bash scripts/build-kimi-plugin.sh",
    "prepare": "npm run build",
    "prepack": "npm run build && npm run build:claude-plugin && npm run build:kimi-plugin"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "typebox": {
      "optional": true
    }
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "^0.80.0",
    "@types/jest": "^30.0.0",
    "@types/node": "^20.0.0",
    "esbuild": "^0.28.1",
    "typebox": "^1.3.0",
    "jest": "^30.4.2",
    "rimraf": "^6.0.1",
    "ts-jest": "^29.0.0",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist",
    "agents",
    "prompts",
    "skills",
    "templates",
    "docs/*.md",
    "src/surfaces/codex/plugin",
    "src/surfaces/claude-code/assets",
    "src/surfaces/claude-code/plugin",
    "src/surfaces/kimi-code",
    "src/surfaces/pi",
    ".claude-plugin",
    "README.md",
    "LICENSE"
  ]
}

{
  "name": "mdocs",
  "version": "2.2.0",
  "description": "Durable initiative and wiki memory for Kimi Code — MCP tools, workflow-enforcement hooks, skills, and an orchestrator agent.",
  "license": "MIT",
  "author": {
    "name": "bbaaxx"
  },
  "keywords": ["kimi-code", "mdocs", "memory", "workflow", "wiki", "initiatives"],
  "interface": {
    "displayName": "Mdocs",
    "shortDescription": "Initiative and wiki memory with enforced workflow gates"
  },
  "skills": "./skills/",
  "agents": "./agents/",
  "sessionStart": {
    "skill": "mdocs-workflow"
  },
  "mcpServers": {
    "mdocs": {
      "command": "node",
      "args": [
        "-e",
        "const path = require('node:path'); const home = process.env.KIMI_CODE_HOME || path.join(require('node:os').homedir(), '.kimi-code'); require(path.join(home, 'plugins', 'managed', 'mdocs', 'dist', 'mcp-server.js')).startMcpServer().catch(error => { console.error(error); process.exit(1); });"
      ]
    }
  },
  "hooks": [
    {
      "event": "PreToolUse",
      "matcher": "Write|Edit|Bash",
      "command": "node ./dist/hooks/pre-tool-use.js",
      "timeout": 10
    },
    {
      "event": "PostToolUse",
      "matcher": "Write|Edit|Bash|Agent|AgentSwarm",
      "command": "node ./dist/hooks/post-tool-use.js",
      "timeout": 10
    },
    {
      "event": "SessionStart",
      "matcher": "startup|resume",
      "command": "node ./dist/hooks/session-start.js",
      "timeout": 10
    }
  ]
}
